//! Geometric predicates over nodes held in the arena.
//!
//! Every expression here mirrors the reference implementation term for term:
//! the products are formed in the same order and compared against zero the same
//! way, so the floating-point results — and therefore the ear-clipping
//! decisions — are bit-identical.

use super::node::Arena;

impl Arena {
    /// Signed area of the triangle `(p, q, r)`.
    pub fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        let (px, py) = (self.x(p), self.y(p));
        let (qx, qy) = (self.x(q), self.y(q));
        let (rx, ry) = (self.x(r), self.y(r));
        (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
    }

    /// Check if two points are equal.
    pub fn equals(&self, p1: usize, p2: usize) -> bool {
        self.x(p1) == self.x(p2) && self.y(p1) == self.y(p2)
    }

    /// Check if a point lies within a convex triangle.
    #[allow(clippy::too_many_arguments)]
    pub fn point_in_triangle(
        ax: f64,
        ay: f64,
        bx: f64,
        by: f64,
        cx: f64,
        cy: f64,
        px: f64,
        py: f64,
    ) -> bool {
        (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
            && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
            && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
    }

    /// `point_in_triangle` for the triangle spanned by three nodes.
    pub fn point_in_triangle_nodes(&self, a: usize, b: usize, c: usize, p: usize) -> bool {
        Arena::point_in_triangle(
            self.x(a),
            self.y(a),
            self.x(b),
            self.y(b),
            self.x(c),
            self.y(c),
            self.x(p),
            self.y(p),
        )
    }

    fn sign(val: f64) -> i32 {
        (0.0 < val) as i32 - (val < 0.0) as i32
    }

    /// For collinear points `p`, `q`, `r`, check if `q` lies on segment `pr`.
    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        self.x(q) <= self.x(p).max(self.x(r))
            && self.x(q) >= self.x(p).min(self.x(r))
            && self.y(q) <= self.y(p).max(self.y(r))
            && self.y(q) >= self.y(p).min(self.y(r))
    }

    /// Check if two segments intersect.
    pub fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = Arena::sign(self.area(p1, q1, p2));
        let o2 = Arena::sign(self.area(p1, q1, q2));
        let o3 = Arena::sign(self.area(p2, q2, p1));
        let o4 = Arena::sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        // collinear cases: an endpoint of one segment lies on the other
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }

        false
    }

    /// Check if a polygon diagonal intersects any polygon segments.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.next(p);
            if self.i(p) != self.i(a)
                && self.i(pn) != self.i(a)
                && self.i(p) != self.i(b)
                && self.i(pn) != self.i(b)
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                return false;
            }
        }
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    pub fn locally_inside(&self, a: usize, b: usize) -> bool {
        if self.area(self.prev(a), a, self.next(a)) < 0.0 {
            self.area(a, b, self.next(a)) >= 0.0 && self.area(a, self.prev(a), b) >= 0.0
        } else {
            self.area(a, b, self.prev(a)) < 0.0 || self.area(a, self.next(a), b) < 0.0
        }
    }

    /// Check if the middle vertex of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.x(a) + self.x(b)) / 2.0;
        let py = (self.y(a) + self.y(b)) / 2.0;
        loop {
            let pn = self.next(p);
            if ((self.y(p) > py) != (self.y(pn) > py))
                && self.y(pn) != self.y(p)
                && (px < (self.x(pn) - self.x(p)) * (py - self.y(p)) / (self.y(pn) - self.y(p))
                    + self.x(p))
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                return inside;
            }
        }
    }

    /// Whether the sector at vertex `m` contains the sector at vertex `p`.
    pub fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.prev(m), m, self.prev(p)) < 0.0
            && self.area(self.next(p), m, self.next(m)) < 0.0
    }

    /// Check if a diagonal between two polygon nodes lies in the polygon interior.
    pub fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        self.i(self.next(a)) != self.i(b)
            && self.i(self.prev(a)) != self.i(b)
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                // does not create opposite-facing sectors
                && (self.area(self.prev(a), a, self.prev(b)) != 0.0
                    || self.area(a, self.prev(b), b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(self.prev(a), a, self.next(a)) > 0.0
                    && self.area(self.prev(b), b, self.next(b)) > 0.0))
    }
}

