//! A from-scratch Rust port of the `mapbox::earcut` polygon triangulation
//! routine (ear clipping with z-order hashing, hole elimination via bridges, and
//! self-intersection fallbacks).
//!
//! Entry point: [`earcut`]. Given a polygon as a list of rings — the first the
//! outer contour, the rest holes — it returns a flat list of vertex indices,
//! three per triangle, indexing into the rings concatenated in order.

pub mod geom;
pub mod node;
pub mod zorder;

use node::{Arena, NIL};
use zorder::{index_curve, ZHash};

/// A 2D point. Mirrors the `util::nth` accessor traits of the C++ original.
pub trait Point {
    fn x(&self) -> f64;
    fn y(&self) -> f64;
}

impl Point for [f64; 2] {
    #[inline]
    fn x(&self) -> f64 {
        self[0]
    }
    #[inline]
    fn y(&self) -> f64 {
        self[1]
    }
}

impl Point for (f64, f64) {
    #[inline]
    fn x(&self) -> f64 {
        self.0
    }
    #[inline]
    fn y(&self) -> f64 {
        self.1
    }
}

/// Output index type. Mirrors the `N` template parameter of `mapbox::earcut<N>`.
pub trait Index: Copy {
    fn from_u32(v: u32) -> Self;
}

impl Index for u16 {
    #[inline]
    fn from_u32(v: u32) -> u16 {
        v as u16
    }
}

impl Index for u32 {
    #[inline]
    fn from_u32(v: u32) -> u32 {
        v
    }
}

impl Index for usize {
    #[inline]
    fn from_u32(v: u32) -> usize {
        v as usize
    }
}

/// Triangulate a polygon given as an outer ring followed by hole rings.
pub fn earcut<N, R, P>(polygon: &[R]) -> Vec<N>
where
    N: Index,
    R: AsRef<[P]>,
    P: Point,
{
    let mut state = Earcut::new();
    state.run(polygon);
    state.indices.into_iter().map(N::from_u32).collect()
}

struct Earcut {
    indices: Vec<u32>,
    vertices: u32,
    arena: Arena,
    hashing: bool,
    hash: ZHash,
}

impl Earcut {
    fn new() -> Earcut {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            arena: Arena::with_capacity(0),
            hashing: false,
            hash: ZHash {
                min_x: 0.0,
                min_y: 0.0,
                inv_size: 0.0,
            },
        }
    }

    fn run<R, P>(&mut self, points: &[R])
    where
        R: AsRef<[P]>,
        P: Point,
    {
        if points.is_empty() {
            return;
        }

        // Rings small enough in aggregate skip the z-order hash entirely; the
        // threshold walk also gives an allocation estimate.
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].as_ref().len() as i32;
            len += points[i].as_ref().len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.arena = Arena::with_capacity(len * 3 / 2);
        self.indices.reserve(len + points[0].as_ref().len());

        let mut outer_node = self.linked_list(points[0].as_ref(), true);
        if outer_node == NIL
            || self.arena.prev(outer_node) == self.arena.next(outer_node)
        {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use a z-order curve hash later;
        // calculate the polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.arena.next(outer_node);
            let mut min_x = self.arena.x(outer_node);
            let mut max_x = min_x;
            let mut min_y = self.arena.y(outer_node);
            let mut max_y = min_y;
            loop {
                let (x, y) = (self.arena.x(p), self.arena.y(p));
                min_x = min_x.min(x);
                min_y = min_y.min(y);
                max_x = max_x.max(x);
                max_y = max_y.max(y);
                p = self.arena.next(p);
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and size are later used to transform coords into
            // integers for the z-order calculation
            let size = (max_x - min_x).max(max_y - min_y);
            self.hash = ZHash {
                min_x,
                min_y,
                inv_size: if size != 0.0 { 32767.0 / size } else { 0.0 },
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    /// Create a circular doubly linked list from polygon points in the
    /// specified winding order.
    fn linked_list<P: Point>(&mut self, points: &[P], clockwise: bool) -> usize {
        let len = points.len();
        let mut last = NIL;

        // calculate original winding order of a polygon ring
        let mut sum = 0.0;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = &points[i];
            let p2 = &points[j];
            sum += (p2.x() - p1.x()) * (p1.y() + p2.y());
            j = i;
        }

        // link points into a circular doubly-linked list in the specified
        // winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.arena.insert_node(
                    self.vertices + i as u32,
                    points[i].x(),
                    points[i].y(),
                    last,
                );
            }
        } else {
            for i in (0..len).rev() {
                last = self.arena.insert_node(
                    self.vertices + i as u32,
                    points[i].x(),
                    points[i].y(),
                    last,
                );
            }
        }

        if last != NIL && self.arena.equals(last, self.arena.next(last)) {
            self.arena.remove_node(last);
            last = self.arena.next(last);
        }

        self.vertices += len as u32;

        last
    }

    /// Eliminate collinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        loop {
            let again;
            let pn = self.arena.next(p);
            if !self.arena.steiner(p)
                && (self.arena.equals(p, pn)
                    && true
                    || self.arena.area(self.arena.prev(p), p, pn) == 0.0)
            {
                self.arena.remove_node(p);
                p = self.arena.prev(p);
                end = p;

                if p == self.arena.next(p) {
                    break;
                }
                again = true;
            } else {
                p = pn;
                again = false;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        if ear == NIL {
            return;
        }
        let mut ear = ear;

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            let hash = ZHash {
                min_x: self.hash.min_x,
                min_y: self.hash.min_y,
                inv_size: self.hash.inv_size,
            };
            index_curve(&mut self.arena, ear, &hash);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.arena.prev(ear) != self.arena.next(ear) {
            let prev = self.arena.prev(ear);
            let next = self.arena.next(ear);

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.arena.i(prev));
                self.indices.push(self.arena.i(ear));
                self.indices.push(self.arena.i(next));

                self.arena.remove_node(ear);

                // skipping the next vertex leads to fewer sliver triangles
                ear = self.arena.next(next);
                stop = self.arena.next(next);

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let e = self.filter_points(ear, NIL);
                    self.earcut_linked(e, 1);
                } else if pass == 1 {
                    // if that didn't work, try curing all small
                    // self-intersections locally
                    let e = self.filter_points(ear, NIL);
                    let e = self.cure_local_intersections(e);
                    self.earcut_linked(e, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.arena.prev(ear);
        let b = ear;
        let c = self.arena.next(ear);

        if self.arena.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.arena.next(self.arena.next(ear));

        while p != self.arena.prev(ear) {
            if self.arena.point_in_triangle_nodes(a, b, c, p)
                && self
                    .arena
                    .area(self.arena.prev(p), p, self.arena.next(p))
                    >= 0.0
            {
                return false;
            }
            p = self.arena.next(p);
        }

        true
    }

    /// `is_ear`, accelerated by walking the z-order list outward from the ear.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.arena.prev(ear);
        let b = ear;
        let c = self.arena.next(ear);

        if self.arena.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.arena.x(a), self.arena.y(a));
        let (bx, by) = (self.arena.x(b), self.arena.y(b));
        let (cx, cy) = (self.arena.x(c), self.arena.y(c));

        // triangle bbox
        let min_tx = ax.min(bx.min(cx));
        let min_ty = ay.min(by.min(cy));
        let max_tx = ax.max(bx.max(cx));
        let max_ty = ay.max(by.max(cy));

        // z-order range for the current triangle bbox
        let min_z = self.hash.z_order(min_tx, min_ty);
        let max_z = self.hash.z_order(max_tx, max_ty);

        let mut p = self.arena.prev_z(ear);
        let mut n = self.arena.next_z(ear);

        let hit = |k: usize| -> bool {
            self.arena.x(k) >= min_tx
                && self.arena.x(k) <= max_tx
                && self.arena.y(k) >= min_ty
                && self.arena.y(k) <= max_ty
                && k != a
                && k != c
                && Arena::point_in_triangle(ax, ay, bx, by, cx, cy, self.arena.x(k), self.arena.y(k))
                && self
                    .arena
                    .area(self.arena.prev(k), k, self.arena.next(k))
                    >= 0.0
        };

        // look for points inside the triangle in both directions
        while p != NIL && self.arena.z(p) >= min_z && n != NIL && self.arena.z(n) <= max_z {
            if hit(p) {
                return false;
            }
            p = self.arena.prev_z(p);

            if hit(n) {
                return false;
            }
            n = self.arena.next_z(n);
        }

        // look for remaining points in decreasing z-order
        while p != NIL && self.arena.z(p) >= min_z {
            if hit(p) {
                return false;
            }
            p = self.arena.prev_z(p);
        }

        // look for remaining points in increasing z-order
        while n != NIL && self.arena.z(n) <= max_z {
            if hit(n) {
                return false;
            }
            n = self.arena.next_z(n);
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.arena.prev(p);
            let pn = self.arena.next(p);
            let b = self.arena.next(pn);

            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
            if !self.arena.equals(a, b)
                && self.arena.intersects(a, p, pn, b)
                && self.arena.locally_inside(a, b)
                && self.arena.locally_inside(b, a)
            {
                self.indices.push(self.arena.i(a));
                self.indices.push(self.arena.i(p));
                self.indices.push(self.arena.i(b));

                // remove the two nodes involved
                self.arena.remove_node(p);
                let pn = self.arena.next(p);
                self.arena.remove_node(pn);

                p = b;
                start = b;
            }
            p = self.arena.next(p);
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// Try splitting the polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.arena.next(self.arena.next(a));
            while b != self.arena.prev(a) {
                if self.arena.i(a) != self.arena.i(b) && self.arena.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.arena.split_polygon(a, b);

                    // filter collinear points around the cuts
                    let an = self.arena.next(a);
                    let a = self.filter_points(a, an);
                    let cn = self.arena.next(c);
                    let c = self.filter_points(c, cn);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.arena.next(b);
            }
            a = self.arena.next(a);
            if a == start {
                return;
            }
        }
    }

    /// Link every hole into the outer ring, left to right.
    fn eliminate_holes<R, P>(&mut self, points: &[R], outer_node: usize) -> usize
    where
        R: AsRef<[P]>,
        P: Point,
    {
        let mut queue: Vec<usize> = Vec::new();
        for ring in points.iter().skip(1) {
            let list = self.linked_list(ring.as_ref(), false);
            if list != NIL {
                if list == self.arena.next(list) {
                    self.arena.set_steiner(list, true);
                }
                let leftmost = self.get_leftmost(list);
                queue.push(leftmost);
            }
        }

        queue.sort_by(|&a, &b| {
            self.arena
                .x(a)
                .partial_cmp(&self.arena.x(b))
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        let mut outer_node = outer_node;
        for &hole in &queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with the outer ring
    /// and link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.arena.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.arena.next(bridge_reverse);
        self.filter_points(bridge_reverse, brn);

        // check if the input node was removed by the filtering
        let bn = self.arena.next(bridge);
        self.filter_points(bridge, bn)
    }

    /// David Eberly's algorithm for finding a bridge between a hole and the
    /// outer polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.arena.x(hole);
        let hy = self.arena.y(hole);
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost vertex to
        // the left; the segment's endpoint with lesser x will be the potential
        // connection vertex
        loop {
            let pn = self.arena.next(p);
            if hy <= self.arena.y(p) && hy >= self.arena.y(pn) && self.arena.y(pn) != self.arena.y(p)
            {
                let x = self.arena.x(p)
                    + (hy - self.arena.y(p)) * (self.arena.x(pn) - self.arena.x(p))
                        / (self.arena.y(pn) - self.arena.y(p));
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.arena.x(p) < self.arena.x(pn) { p } else { pn };
                    if x == hx {
                        // hole touches outer segment; pick the leftmost endpoint
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of the hole vertex, the segment
        // intersection and the endpoint; if there are none, we have a valid
        // connection. Otherwise choose the vertex of minimum angle with the ray
        // as the connection vertex.
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.arena.x(m);
        let my = self.arena.y(m);

        let mut p = m;
        loop {
            let px = self.arena.x(p);
            let py = self.arena.y(p);
            if hx >= px
                && px >= mx
                && hx != px
                && Arena::point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px);

                if self.arena.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.arena.x(m) || self.arena.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.arena.next(p);
            if p == stop {
                break;
            }
        }

        m
    }

    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.arena.x(p) < self.arena.x(leftmost)
                || (self.arena.x(p) == self.arena.x(leftmost)
                    && self.arena.y(p) < self.arena.y(leftmost))
            {
                leftmost = p;
            }
            p = self.arena.next(p);
            if p == start {
                break;
            }
        }
        leftmost
    }
}

