toolUseResult.originalFile:
//! Z-order (Morton) curve hashing used to speed up the ear test on large rings,
//! plus Simon Tatham's iterative linked-list merge sort that orders the nodes by
//! their z value.

use super::node::{Arena, NIL};

/// Bounding box + scale factor used to quantize coordinates for hashing.
pub struct ZHash {
    pub min_x: f64,
    pub min_y: f64,
    pub inv_size: f64,
}

impl ZHash {
    /// Z-order of a vertex given the coords and the size of the data bounding box.
    pub fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }
}

/// Interlink polygon nodes in z-order.
pub fn index_curve(arena: &mut Arena, start: usize, hash: &ZHash) {
    debug_assert!(start != NIL);
    let mut p = start;

    loop {
        if arena.z(p) == 0 {
            let z = hash.z_order(arena.x(p), arena.y(p));
            arena.set_z(p, z);
        }
        let (prev, next) = (arena.prev(p), arena.next(p));
        arena.set_prev_z(p, prev);
        arena.set_next_z(p, next);
        p = next;
        if p == start {
            break;
        }
    }

    let pz = arena.prev_z(p);
    arena.set_next_z(pz, NIL);
    arena.set_prev_z(p, NIL);

    sort_linked(arena, p);
}

/// Simon Tatham's linked list merge sort algorithm, over the `next_z` chain.
pub fn sort_linked(arena: &mut Arena, list: usize) -> usize {
    debug_assert!(list != NIL);
    let mut list = list;
    let mut in_size: i32 = 1;

    loop {
        let mut p = list;
        list = NIL;
        let mut tail = NIL;
        let mut num_merges = 0;

        while p != NIL {
            num_merges += 1;
            let mut q = p;
            let mut p_size: i32 = 0;
            for _ in 0..in_size {
                p_size += 1;
                q = arena.next_z(q);
                if q == NIL {
                    break;
                }
            }

            let mut q_size = in_size;

            while p_size > 0 || (q_size > 0 && q != NIL) {
                let e;
                if p_size == 0 {
                    e = q;
                    q = arena.next_z(q);
                    q_size -= 1;
                } else if q_size == 0 || q == NIL {
                    e = p;
                    p = arena.next_z(p);
                    p_size -= 1;
                } else if arena.z(p) <= arena.z(q) {
                    e = p;
                    p = arena.next_z(p);
                    p_size -= 1;
                } else {
                    e = q;
                    q = arena.next_z(q);
                    q_size -= 1;
                }

                if tail != NIL {
                    arena.set_next_z(tail, e);
                } else {
                    list = e;
                }

                arena.set_prev_z(e, tail);
                tail = e;
            }

            p = q;
        }

        if tail != NIL {
            arena.set_next_z(tail, NIL);
        }

        if num_merges <= 1 {
            return list;
        }

        in_size *= 2;
    }
}

