// Port of tests/test10.cpp: build a set of concentric polygon rings (ring 0 is
// the outer contour, the rest are treated as holes), triangulate with earcut,
// and print the resulting index list.

#[path = "src/earcut/mod.rs"]
mod earcut;

use std::f64::consts::PI;
use std::io::Write;

/// `std::atoi`: skip leading whitespace, take an optional sign and the longest
/// run of digits, and yield 0 when there is nothing numeric to read.
fn atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut k = 0;
    while k < b.len() && (b[k] as char).is_ascii_whitespace() {
        k += 1;
    }

    let mut neg = false;
    if k < b.len() && (b[k] == b'+' || b[k] == b'-') {
        neg = b[k] == b'-';
        k += 1;
    }

    let mut n: i64 = 0;
    while k < b.len() && b[k].is_ascii_digit() {
        n = n * 10 + (b[k] - b'0') as i64;
        if n > i32::MAX as i64 + 1 {
            n = i32::MAX as i64 + 1;
        }
        k += 1;
    }

    let n = if neg { -n } else { n };
    n.clamp(i32::MIN as i64, i32::MAX as i64) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 10;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();

    for layer in 0..n {
        let mut ring: Vec<[f64; 2]> = Vec::new();
        let radius = (layer + 1) as f64 * 0.3;

        for i in 0..(layer + 3) * 2 {
            let angle = 2.0 * PI * i as f64 / (((layer + 3) * 2) as f64);
            let offset = layer as f64 * 0.1;
            ring.push([
                (radius + offset) * angle.cos(),
                (radius + offset) * angle.sin(),
            ]);
        }

        polygon.push(ring);
    }

    let indices = earcut::earcut::<u32, _, _>(&polygon);

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for idx in indices {
        write!(out, "{} ", idx).unwrap();
    }
    out.flush().unwrap();
}

