fn concave_comb() {
    // Zig-zag teeth force real ear selection rather than a fan.
    let mut pts = vec![(0.0, 0.0)];
    for k in 0..6 {
        let x = k as f64;
        pts.push((x + 0.4, 0.0));
        pts.push((x + 0.4, 2.0));
        pts.push((x + 0.6, 2.0));
        pts.push((x + 0.6, 0.0));
    }
    pts.push((6.0, 0.0));
    pts.push((6.0, -1.0));
    pts.push((0.0, -1.0));
    check(&[ring(&pts)]);
