    // 200 outer vertices trips the 80-vertex threshold, so isEarHashed and the
    // z-order merge sort drive the ear test here.
    let mut outer = Vec::new();
    for i in 0..200 {
        let a = 2.0 * std::f64::consts::PI * i as f64 / 200.0;
        outer.push([10.0 * a.cos(), 10.0 * a.sin()]);
    }
    let mut polygon = vec![outer];
    for &(cx, cy) in &[(-4.0, 0.0), (4.0, 0.0), (0.0, 5.0)] {
        let mut hole = Vec::new();
        for i in 0..24 {
