fn degenerate_inputs_yield_nothing() {
    let empty: Vec<Vec<[f64; 2]>> = Vec::new();
    assert!(earcut::<u32, _, _>(&empty).is_empty());
    assert!(earcut::<u32, _, _>(&[ring(&[])]).is_empty());
    assert!(earcut::<u32, _, _>(&[ring(&[(0.0, 0.0), (1.0, 1.0)])]).is_empty());
    // duplicate closing vertex collapses to a triangle-less ring
    assert!(earcut::<u32, _, _>(&[ring(&[(0.0, 0.0), (1.0, 1.0), (1.0, 1.0)])]).is_empty());
}

