//! Self-validation for the triangulator. The `test10` polygon only exercises a
//! convex outer ring (its "holes" all fall outside and get dropped), so these
//! cover the paths it never reaches: hole bridging, z-order hashing, and
//! collinear-point filtering.
//!
//! The invariants checked are the ones a correct triangulation must satisfy:
//! every index is in range, the triangle count is `V + 2H - 2`, and the total
//! triangle area equals the polygon area.

use super::earcut;

fn ring(pts: &[(f64, f64)]) -> Vec<[f64; 2]> {
    pts.iter().map(|&(x, y)| [x, y]).collect()
}

/// Sum of unsigned triangle areas.
fn tri_area(polygon: &[Vec<[f64; 2]>], indices: &[u32]) -> f64 {
    let flat: Vec<[f64; 2]> = polygon.iter().flatten().copied().collect();
    let mut total = 0.0;
    for t in indices.chunks(3) {
        let (a, b, c) = (
            flat[t[0] as usize],
            flat[t[1] as usize],
            flat[t[2] as usize],
        );
        total += ((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])).abs() / 2.0;
    }
    total
}

/// Shoelace area of a ring, unsigned.
fn ring_area(r: &[[f64; 2]]) -> f64 {
    let mut sum = 0.0;
    for i in 0..r.len() {
        let j = (i + 1) % r.len();
        sum += r[i][0] * r[j][1] - r[j][0] * r[i][1];
    }
    (sum / 2.0).abs()
}

fn check(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let indices: Vec<u32> = earcut(polygon);
    let total: usize = polygon.iter().map(|r| r.len()).sum();

    assert_eq!(indices.len() % 3, 0, "indices must come in triples");
    for &i in &indices {
        assert!((i as usize) < total, "index {} out of range {}", i, total);
    }

    let expected = ring_area(&polygon[0]) - polygon[1..].iter().map(|r| ring_area(r)).sum::<f64>();
    let got = tri_area(polygon, &indices);
    assert!(
        (got - expected).abs() < 1e-9 * expected.max(1.0),
        "area mismatch: got {}, expected {}",
        got,
        expected
    );

    // V + 2H - 2 triangles for a fully triangulated polygon with H holes
    let tris = total + 2 * (polygon.len() - 1) - 2;
    assert_eq!(indices.len(), tris * 3, "triangle count");

    indices
}

