        r.push([0.3 * a.cos(), 0.3 * a.sin()]);
    }
    let indices: Vec<u32> = earcut(&[r]);
    assert_eq!(indices, vec![4, 5, 0, 0, 1, 2, 2, 3, 4, 4, 0, 2]);
}

#[test]
fn square_with_square_hole() {
    let polygon = vec![
        ring(&[(0.0, 0.0), (4.0, 0.0), (4.0, 4.0), (0.0, 4.0)]),
        ring(&[(1.0, 1.0), (1.0, 3.0), (3.0, 3.0), (3.0, 1.0)]),
