        let x = k as f64;
        pts.push((x + 0.4, 0.0));
        pts.push((x + 0.4, 2.0));
        pts.push((x + 0.6, 2.0));
        pts.push((x + 0.6, 0.0));
    }
    pts.push((6.0, 0.0));
