toolUseResult.originalFile:
//! Circular doubly-linked list of polygon vertices, stored in a flat arena.
//!
//! The reference C++ implementation links raw `Node*` pointers allocated from an
//! object pool. Here the pool is a `Vec<Node>` and every link is an index into
//! it, with `NIL` standing in for a null pointer. Indices are stable because
//! nodes are never removed from the arena, only unlinked from the rings.

/// Stand-in for a null `Node*`.
pub const NIL: usize = usize::MAX;

pub struct Node {
    /// Index of the vertex in the original (flattened) input sequence.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in a polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

/// Arena owning every node ever created, plus the primitive link operations.
pub struct Arena {
    nodes: Vec<Node>,
}

impl Arena {
    pub fn with_capacity(cap: usize) -> Arena {
        Arena {
            nodes: Vec::with_capacity(cap),
        }
    }

    #[inline]
    pub fn get(&self, k: usize) -> &Node {
        &self.nodes[k]
    }

    #[inline]
    pub fn x(&self, k: usize) -> f64 {
        self.nodes[k].x
    }

    #[inline]
    pub fn y(&self, k: usize) -> f64 {
        self.nodes[k].y
    }

    #[inline]
    pub fn i(&self, k: usize) -> u32 {
        self.nodes[k].i
    }

    #[inline]
    pub fn prev(&self, k: usize) -> usize {
        self.nodes[k].prev
    }

    #[inline]
    pub fn next(&self, k: usize) -> usize {
        self.nodes[k].next
    }

    #[inline]
    pub fn z(&self, k: usize) -> i32 {
        self.nodes[k].z
    }

    #[inline]
    pub fn prev_z(&self, k: usize) -> usize {
        self.nodes[k].prev_z
    }

    #[inline]
    pub fn next_z(&self, k: usize) -> usize {
        self.nodes[k].next_z
    }

    #[inline]
    pub fn set_steiner(&mut self, k: usize, v: bool) {
        self.nodes[k].steiner = v;
    }

    #[inline]
    pub fn steiner(&self, k: usize) -> bool {
        self.nodes[k].steiner
    }

    #[inline]
    pub fn set_z(&mut self, k: usize, v: i32) {
        self.nodes[k].z = v;
    }

    #[inline]
    pub fn set_prev_z(&mut self, k: usize, v: usize) {
        self.nodes[k].prev_z = v;
    }

    #[inline]
    pub fn set_next_z(&mut self, k: usize, v: usize) {
        self.nodes[k].next_z = v;
    }

    /// Allocate a fresh, unlinked node.
    pub fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        });
        self.nodes.len() - 1
    }

    /// Create a node and optionally link it into a ring after `last`.
    pub fn insert_node(&mut self, i: u32, x: f64, y: f64, last: usize) -> usize {
        let p = self.construct(i, x, y);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    /// Unlink a node from its ring and from the z-order list.
    pub fn remove_node(&mut self, p: usize) {
        let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let (prev_z, next_z) = (self.nodes[p].prev_z, self.nodes[p].next_z);
        if prev_z != NIL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NIL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }

    /// Link two polygon vertices with a bridge.
    ///
    /// If the vertices belong to the same ring this splits the polygon in two;
    /// if one belongs to the outer ring and the other to a hole, it merges them
    /// into a single ring.
    pub fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.construct(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.construct(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }
}
